<script setup>
import {ref,watch,computed,onUnmounted} from 'vue'
import {ElMessageBox} from 'element-plus'
import {api,yuan,date,statuses,refundStatuses,notify,run,upload} from '../lib'
const props=defineProps({id:[Number,String],admin:Boolean}),emit=defineEmits(['changed','close']),order=ref(null),busy=ref(false),refundOpen=ref(false),reviewOpen=ref(false),refundForm=ref({}),reviewForm=ref({images:[]}),previews=ref([]),paymentOpen=ref(false),uploading=ref(false)
const address=computed(()=>{try{return JSON.parse(order.value?.address_snapshot||'{}')}catch{return{}}})
async function load(){if(props.id)order.value=await api.get((props.admin?'/admin/order/':'/order/')+props.id)}
watch(()=>props.id,()=>run(load),{immediate:true})
async function action(name,body={}){if(busy.value)return;busy.value=true;try{if(props.admin)await api.put('/admin/order/'+name+'/'+props.id,body);else if(name==='cancel')await api.put('/order/cancel/'+props.id);else await api.post('/payment/mock/'+props.id+(name==='fail'?'/fail':''));paymentOpen.value=false;await load();emit('changed');notify('操作已处理')}finally{busy.value=false}}
async function reject(){const {value}=await ElMessageBox.prompt('请填写拒单原因，拒单后自动创建全额剩余金额退款。','拒绝订单',{inputValidator:v=>!!v?.trim()||'请填写原因'});await action('reject',{reason:value})}
function refund(){refundForm.value={order_id:Number(props.id),amount:Number(order.value.total)-Number(order.value.refunded),reason:'不再需要',remark:''};refundOpen.value=true}
async function sendRefund(){if(busy.value)return;busy.value=true;try{await api.post('/refund/apply',refundForm.value);refundOpen.value=false;await load();emit('changed');notify('退款申请已提交，等待商家审核')}finally{busy.value=false}}
function review(item){reviewForm.value={order_item_id:item.id,rating:5,content:'',images:[]};clearPreviews();reviewOpen.value=true}
function clearPreviews(){previews.value.forEach(p=>URL.revokeObjectURL(p.url));previews.value=[]}
async function photos(e){const files=[...e.target.files];e.target.value='';if(files.length+previews.value.length>9)return notify('最多选择9张图片');uploading.value=true;try{for(let file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){notify('仅支持5MB以内的JPG、PNG、WEBP');continue}previews.value.push({file,url:URL.createObjectURL(file)})}}finally{uploading.value=false}}
function removePhoto(index){URL.revokeObjectURL(previews.value[index].url);previews.value.splice(index,1)}
async function sendReview(){if(busy.value)return;busy.value=true;try{const urls=[];for(let p of previews.value){if(!p.uploaded)p.uploaded=(await upload(p.file,'review')).url;urls.push(p.uploaded)}await api.post('/review/add',{...reviewForm.value,images:urls});reviewOpen.value=false;clearPreviews();notify('评价已提交，谢谢这份分享');await load();emit('changed')}finally{busy.value=false}}
onUnmounted(clearPreviews)
</script>
<template><div v-if="order" class="order-panel"><div class="row-between"><span class="eyebrow">{{order.order_no}}</span><span class="status-tag" :class="'status-'+order.status">{{statuses[order.status]}}</span></div><div class="order-progress" v-if="order.status<=5"><span v-for="(label,i) in ['待支付','待接单','已接单','制作中','配送中','已完成']" :key="i" :class="{done:order.status>=i}"><i>{{order.status>i?'✓':i+1}}</i>{{label}}</span></div><div class="order-item" v-for="item in order.items" :key="item.id"><img :src="item.cover" :alt="item.name"/><div><h4>{{item.name}}</h4><p>{{item.specification}}</p><span>¥ {{yuan(item.price)}} × {{item.quantity}}</span></div><button v-if="!admin&&order.status===5&&!item.reviewed" class="btn small" @click="review(item)">评价鲜花</button><span class="subtle" v-else-if="item.reviewed">已评价</span></div><dl class="order-info"><dt>收花信息</dt><dd>{{address.receiver}} · {{address.phone}}<br>{{address.province}}{{address.city}}{{address.district}}{{address.detail}}</dd><dt>随花祝福</dt><dd class="preserve-lines">{{order.greeting||'未填写'}}</dd><dt>订单备注</dt><dd>{{order.remark||'无'}}</dd><dt>创建时间</dt><dd>{{date(order.create_time)}}</dd><dt>支付状态</dt><dd>{{order.payment_status===1?'模拟支付成功':'未支付'}} <span v-if="order.pay_time"> · {{date(order.pay_time)}}</span></dd><dt>退款金额</dt><dd>¥ {{yuan(order.refunded)}}</dd><template v-if="order.reject_reason"><dt>拒绝原因</dt><dd>{{order.reject_reason}}</dd></template></dl><div class="row-between order-amount"><span>订单金额</span><strong>¥ {{yuan(order.total)}}</strong></div><div class="order-actions" v-if="!admin"><template v-if="order.status===0"><button class="btn" :disabled="busy" @click="run(async()=>{await ElMessageBox.confirm('取消订单并释放预留库存？','取消订单');await action('cancel')})">取消订单</button><button class="btn primary" @click="paymentOpen=true">前往模拟支付</button></template><button class="btn" v-if="order.payment_status===1&&![6,7].includes(order.status)&&Number(order.refunded)<Number(order.total)" @click="refund">申请退款</button></div><div class="order-actions" v-else><template v-if="order.status===1"><button class="btn danger-button" :disabled="busy" @click="run(reject)">拒绝接单</button><button class="btn primary" :disabled="busy" @click="run(()=>action('accept'))">接受订单</button></template><button v-if="order.status>=2&&order.status<=4" class="btn primary" :disabled="busy" @click="run(()=>action('status',{status:order.status+1}))">{{['','','开始制作','安排配送','完成订单'][order.status]}}</button></div><div v-if="order.refunds.length" class="refund-timeline"><h3>退款进度</h3><article v-for="r in order.refunds" :key="r.id"><div class="row-between"><span>{{refundStatuses[r.refund_status]}}</span><b>¥ {{yuan(r.refund_amount)}}</b></div><p>{{r.refund_reason}}</p><p v-if="r.reject_reason" class="danger">拒绝原因：{{r.reject_reason}}</p><p v-if="r.fail_reason" class="danger">失败原因：{{r.fail_reason}}</p><small>{{date(r.create_time)}} · {{r.refund_no}}</small></article></div><el-dialog v-model="paymentOpen" title="模拟支付 · 仅供测试" width="440px" append-to-body align-center><div class="mock-payment"><Icon name="bag" :size="40"/><h2>¥ {{yuan(order.total)}}</h2><p>此操作仅验证订单流程，不扣款、不调用真实支付渠道。</p><button class="btn primary" :disabled="busy" @click="run(()=>action('pay'))">模拟支付成功</button><button class="btn" :disabled="busy" @click="run(()=>action('fail'))">模拟支付失败</button></div></el-dialog><el-dialog v-model="refundOpen" title="申请模拟退款" width="500px" append-to-body><form class="stack-form" @submit.prevent="run(sendRefund)"><p class="subtle">支持部分退款。制作后是否同意退款由商家根据履约情况审核；制作后的花材不自动恢复库存。</p><label>退款金额<input type="number" v-model="refundForm.amount" required min="0.01" :max="Number(order.total)-Number(order.refunded)" step="0.01"/></label><label>退款原因<select v-model="refundForm.reason"><option v-for="s in ['不再需要','商品信息错误','购买错误','配送时间不合适','商品质量问题','其他原因']" :key="s">{{s}}</option></select></label><label>补充说明<textarea v-model="refundForm.remark" maxlength="500" rows="3"/></label><button class="btn primary" :disabled="busy">提交退款申请</button></form></el-dialog><el-dialog v-model="reviewOpen" title="分享收到花的故事" width="560px" append-to-body @closed="clearPreviews"><form class="stack-form" @submit.prevent="run(sendReview)"><label>花束评分<el-rate v-model="reviewForm.rating"/></label><label>你的评价<textarea v-model="reviewForm.content" maxlength="2000" required rows="4" placeholder="花束与想象中一样吗？说说你的感受…"/></label><label>上传实拍图片 <small>最多9张，每张不超过5MB</small><input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="run(()=>photos($event))"/></label><div class="upload-previews"><div v-for="(p,i) in previews" :key="p.url"><img :src="p.url" alt="待提交评价图片"/><button type="button" @click="removePhoto(i)" aria-label="删除待提交图片">×</button></div></div><button class="btn primary" :disabled="busy||uploading">{{busy?'正在上传并提交…':'提交真实评价'}}</button></form></el-dialog></div><div v-else class="empty">正在读取订单…</div></template>
